import {find,isLocked} from '../document/model.js';
import {currentMesh,editMesh} from '../scene/mesh-edit.js';
export function showMeshColour(a){
 const n=find(a.doc,a.selected[0]);if(!n?.mesh||isLocked(a.doc,n.id))return;
 a.pause();a.properties.flush();const index=Math.min(a.activeMesh||0,currentMesh(n,a.time).points.length-1),initial=currentMesh(n,a.time).points[index].color;
 const palette=['#ffffff','#000000','#ff625f','#ffb84d','#ffe066','#65d49a','#59cbe8','#6477eb','#b87ee8','#ed85b2'];
 const d=a.dialog('Mesh point '+(index+1)+' colour',`<form><p>Choose a swatch, adjust the sliders, or enter a hex colour.</p><div class="mesh-palette">${palette.map(c=>`<button type="button" data-swatch="${c}" aria-label="Colour ${c}" style="background:${c};width:44px;height:44px"></button>`).join('')}</div><div data-colour-preview style="height:48px;margin:12px 0;border-radius:8px;background:${initial}"></div>${['Red','Green','Blue'].map((c,i)=>`<label>${c}<input aria-label="${c}" data-channel="${i}" type="range" min="0" max="255" value="${parseInt(initial.slice(1+i*2,3+i*2),16)}"></label>`).join('')}<label>Hex colour<input name="colour" aria-label="Hex colour" value="${initial}" pattern="#[0-9a-fA-F]{6}" required></label><div class="dialog-actions"><button type="button" data-close>Cancel</button><button type="submit" class="primary">Apply colour</button></div></form>`,(form,dialog)=>{const color=form.get('colour');if(!/^#[0-9a-f]{6}$/i.test(color))throw Error('Enter six hex digits after #.');a.mutate('Mesh point colour',()=>editMesh(n,a.time,m=>{m.points[index].color=color;return m;}));a.rememberColor(color);dialog.close();});
 const channels=[...d.querySelectorAll('[data-channel]')],hex=d.querySelector('[name=colour]'),preview=d.querySelector('[data-colour-preview]');
 const update=color=>{hex.value=color;preview.style.background=color;channels.forEach((el,i)=>el.value=parseInt(color.slice(1+i*2,3+i*2),16));};
 d.querySelectorAll('[data-swatch]').forEach(el=>el.onclick=()=>update(el.dataset.swatch));channels.forEach(el=>el.oninput=()=>update('#'+channels.map(x=>Number(x.value).toString(16).padStart(2,'0')).join('')));hex.oninput=()=>{if(/^#[0-9a-f]{6}$/i.test(hex.value))update(hex.value);};
}
